{"question": "Dấu hiệu lâm sàng nào giúp xác định chẩn đoán gãy toàn bộ xương hàm trên dạng gãy ngang?", "claim": "Chẩn đoán xác định gãy ngang trong trường hợp gãy toàn bộ xương hàm trên dựa vào dấu hiệu có sự di động của xương hàm trên.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng ghi nhận tình trạng gãy ngang của xương hàm trên toàn bộ đi kèm với triệu chứng lâm sàng là xương hàm trên có dấu hiệu di động."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Có dấu hiệu di động xương hàm trên."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "- Sử dụng khí cụ có máng cắn phía sau tạo lực tác động làm lún các răng sau, làm cho xương hàm dưới xoay ra trước và lên trên làm đóng cắn hở, đồng thời hạn chế sự phát triển của xương hàm theo chiều đứng."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["55. GÃY XƯƠNG HÀM TRÊN", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Gãy toàn bộ", "b. Gãy ngang"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["20 . KHỚP CẮN HỞ", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "2.2. Khớp cắn hở do xương hàm", "a. Bệnh nhân đang trong thời kỳ tăng trưởng"]}]}
