ackage{wasysym} \\usepackage{amsfonts} \\usepackage{amssymb} \\usepackage{amsbsy} \\usepackage{mathrsfs} \\usepackage{upgreek} \\setlength{\\oddsidemargin}{-69pt} \\begin{document}$$4*{10}^{6}$$\\end{document} MSCs per gland was used. In the trial by C. Grønhøj et al., the amount was dependent on the volume of the submandibular"}], "public_sources": [{"evidence_id": "P1", "title": "Effectiveness of pharmaceutical preparations of Periplaneta Americana (KangFuXin liquid) in the treatment of chronic gingivitis in children with orthodontic problems: A systematic review and meta-analysis of randomized controlled trials", "heading_path": ["Body", "2. Methods and materials", "2.8. Publication bias and sensitivity analysis"]}, {"evidence_id": "P2", "title": "Treatment of Xerostomia with Mesenchymal Stem Cells – A Systematic Review and Meta-Analysis of Clinical Trials", "heading_path": ["Body", "Efficacy of MSC treatment", "Number of Injected MSCs"]}]}
