{"question": "Ung thư mũi họng hoại tử có thể đi kèm triệu chứng nuốt khó và là một trong những nguyên nhân gây hôi miệng không?", "claim": "Ung thư mũi họng hoại tử có triệu chứng đi kèm là nuốt khó và được xếp vào nhóm nguyên nhân gây hơi thở hôi cần đánh giá lâm sàng.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu nội bộ và quy chuẩn xác nhận ung thư mũi họng hoại tử đi kèm triệu chứng nuốt khó và gây tình trạng hơi thở hôi."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Một số nguyên nhân gây hôi miệng"}, {"quote_id": "P1.Q2", "evidence_id": "P1", "text": "Nguyên nhân | Những phát hiện gợi ý | Tiếp cận chẩn đoán"}, {"quote_id": "P1.Q3", "evidence_id": "P1", "text": "Ung thư miệng hoại tử (hiếm gặp - thường được chẩn đoán trước khi tiến triển thành hoại tử) | Tổn thương có thể nhận biết được qua thăm khám Trên bệnh nhân lớn tuổi, những người thường có tiền sử sử dụng rượu, thuốc lá, hoặc cả hai | Sinh thiết, CT, hoặc MRI"}, {"quote_id": "P2.Q4", "evidence_id": "P2", "text": "Một số nguyên nhân gây hôi miệng"}, {"quote_id": "P2.Q5", "evidence_id": "P2", "text": "Nguyên nhân | Những phát hiện gợi ý | Tiếp cận chẩn đoán"}, {"quote_id": "P2.Q6", "evidence_id": "P2", "text": "Ung thư mũi họng hoại tử* | Nuốt khó | Đánh giá lâm sàng"}], "public_sources": [{"evidence_id": "P1", "title": "Hơi thở hôi", "heading_path": ["Nguyên nhân Bệnh hôi miệng", "Một số nguyên nhân gây hôi miệng"]}, {"evidence_id": "P2", "title": "Hơi thở hôi", "heading_path": ["Nguyên nhân Bệnh hôi miệng", "Một số nguyên nhân gây hôi miệng"]}]}
