{"question": "Các dấu hiệu lâm sàng nào thường gặp trong chẩn đoán xác định ung thư lưỡi?", "claim": "Bệnh nhân ung thư lưỡi trên lâm sàng hoàn toàn không xuất hiện các tổn thương vết trắng hay vết đỏ.", "internal_evidence": [{"evidence_id": "I1", "content": "Phác đồ khoa ung bướu ghi nhận triệu chứng biểu hiện của ung thư lưỡi bao gồm các tổn thương dạng bạch sản (vết trắng), hồng sản (vết đỏ) hoặc dạng hỗn hợp đỏ trắng trên niêm mạc."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Gãy xương hàm trên luôn có các triệu chứng lâm sàng và X quang rõ rệt nên không cần chẩn đóan phân biệt. Lưu ý : phát hiện các trường hợp có chấn thương sọ não kèm theo để xử trí thích hợp."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Các tổn thương vết trắng (bạch sản), vết đỏ (hồng sản) hoặc đỏ trắng."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["55. GÃY XƯƠNG HÀM TRÊN", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["49. UNG THƯ LƯỠI", "III. CHẨN ĐOÁN", "1 Chẩn đoán xác định", "1.1. Lâm sàng"]}]}
