{"question": "Kết quả khám lâm sàng lỗ ống Stenon trong bệnh lý u hỗn hợp tuyến nước bọt mang tai như thế nào?", "claim": "Khám lỗ ống Stenon ở bệnh nhân u hỗn hợp tuyến nước bọt mang tai thấy bình thường.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu Chương 4 về động học cắn khớp mô tả đoạn đóng-ra trước và trượt từ tiếp xúc lui sau đến ra trong, không đề cập đến u tuyến nước bọt hay ống Stenon."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Khám thấy khối sưng vùng tuyến dưới hàm ranh giới rõ, mật độ chắc, di động cùng với tuyến, da trên u bình thường nếu không bội nhiễm"}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Khám lỗ ống Stenon thấy bình thườ ng."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["46. U TUYẾN NƯỚC BỌT DƯỚI HÀM", "III. CHẨN ĐOÁN", "1 Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["45. U HỖ N HỢ P TUYẾ N NƯỚ C BỌ T MANG TAI", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1 Lâm sàng"]}]}
