{"question": "Đặc điểm lâm sàng tại chỗ của u tuyến nước bọt dưới hàm được mô tả như thế nào?", "claim": "Khám lâm sàng u tuyến nước bọt dưới hàm thấy khối sưng vùng tuyến dưới hàm có ranh giới rõ, mật độ chắc và di động cùng với tuyến, da trên u bình thường nếu không bội nhiễm.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu chuyên khoa ghi nhận khối u tuyến dưới hàm khi khám thường thấy ranh giới rõ, chắc, di động theo tuyến và da phủ bình thường khi chưa bị bội nhiễm."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- CT Scanner: có khối thấu quang ranh giới rõ ở vùng sàn miệng, và có thể thấy hình ảnh sỏi ống tuyến nước bọt dưới hàm."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Khám thấy khối sưng vùng tuyến dưới hàm ranh giới rõ, mật độ chắc, di động cùng với tuyến, da trên u bình thường nếu không bội nhiễm"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["32. ÁP XE VÙNG SÀN MIỆNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Cận lâm sàng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["46. U TUYẾN NƯỚC BỌT DƯỚI HÀM", "III. CHẨN ĐOÁN", "1 Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}]}
