{"question": "Viêm tủy răng có hồi phục có bắt buộc phải biểu hiện triệu chứng đau hay ê buốt trên lâm sàng không?", "claim": "Viêm tủy có hồi phục có thể không biểu hiện triệu chứng lâm sàng rõ rệt.", "internal_evidence": [{"evidence_id": "I1", "content": "Viêm tủy răng có hồi phục là tình trạng viêm nhẹ của tủy răng, thường xảy ra do các kích thích từ bên ngoài như sâu răng hoặc mòn cổ răng. Bệnh nhân thường cảm thấy ê buốt thoáng qua khi tiếp xúc với các tác nhân kích thích nóng hoặc lạnh, nhưng cảm giác này sẽ biến mất ngay sau khi loại bỏ tác nhân đó."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Triệu chứng | Viêm tủy không hồi phục | Viêm tủy có hồi phục | Viêm quanh cuống cấp"}, {"quote_id": "P1.Q2", "evidence_id": "P1", "text": "Tính chất cơn đau | Đau có tính lan tỏa. | Đau tại răng. | Đau khu trú rõ tại răng tổn thương."}, {"quote_id": "P2.Q3", "evidence_id": "P2", "text": "+ Viêm tủy có hồi phục có thể không biểu hiện triệu chứng."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["5. VIÊM TỦY RĂNG SỮA", "III. CHẨN ĐOÁN", "2. Viêm tủy răng sữa không hồi phục", "c. Chẩn đoán phân biệt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["11. VIÊM TỦY RĂNG", "III. CHẨN ĐOÁN", "1. Viêm tủy có hồi phục", "1.1. Chẩn đoán xác định"]}]}
