{"question": "Các nghiên cứu về phương pháp cảm ứng viêm lợi thực nghiệm thường có sự khác biệt gì về tiêu chí đánh giá kết quả?", "claim": "Các nghiên cứu về phương pháp cảm ứng viêm lợi thực nghiệm có sự khác biệt về tiêu chí đánh giá giữa chỉ số lâm sàng và hồ sơ phân tử, làm hạn chế khả năng tổng hợp dữ liệu.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu nội bộ ghi nhận các nghiên cứu thực nghiệm viêm lợi khác nhau về trọng tâm điểm kết thúc, bao gồm cả chỉ số lâm sàng và cơ chế phân tử."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Table 2"}, {"quote_id": "P1.Q2", "evidence_id": "P1", "text": "Study design of each selected study"}, {"quote_id": "P1.Q3", "evidence_id": "P1", "text": "Drug/Drug class (number of records) | References | Study design"}, {"quote_id": "P1.Q4", "evidence_id": "P1", "text": "Suplatast tosilate (1) | Murata et al.37 | Case report and review of the literature"}, {"quote_id": "P2.Q5", "evidence_id": "P2", "text": "Table 2"}, {"quote_id": "P2.Q6", "evidence_id": "P2", "text": "Key Methodological Differences Among Included Experimental Gingivitis Studies"}, {"quote_id": "P2.Q7", "evidence_id": "P2", "text": "Methodological Element | Variation Observed | Implication for Study Design"}, {"quote_id": "P2.Q8", "evidence_id": "P2", "text": "Outcome Focus | Clinical indices vs molecular profiles | Studies differ in endpoint emphasis, limiting synthesis across clinical and mechanistic outcomes"}], "public_sources": [{"evidence_id": "P1", "title": "Drug-Related Halitosis: A Narrative Review", "heading_path": ["Body", "Methods", "Screening and data selection"]}, {"evidence_id": "P2", "title": "Systematic Review of Experimental Gingivitis Induction Methods: Methodological Variations and Their Impact on Inflammation Progression", "heading_path": ["Body", "Results", "Study Characteristics"]}]}
