sdiagnosis | Dentoalveolar abscess | Acute | Chronic | Apical periodontitis | Acute | Chronic"}, {"quote_id": "P2.Q9", "evidence_id": "P2", "text": "Total N (%) | 13 (100) | 5 (38.5) | 4 (80) | 1 (20) | 8 (61.5) | 2 (25) | 6 (75)"}, {"quote_id": "P2.Q10", "evidence_id": "P2", "text": "Pain N (%) | Yes, 2 (66.6)No, 1 (33.3) | Yes, 1 (100) | Yes, 1 (100) | - | Yes, 1 (50)No, 1 (50) | - | Yes, 1 (50)No, 1 (50)"}], "public_sources": [{"evidence_id": "P1", "title": "Prevalence of dizziness in patients with temporomandibular disorders: a systematic review and meta-analysis", "heading_path": ["Body", "3. Results", "3.4 Groups and parameters observed"]}, {"evidence_id": "P2", "title": "Clinical Differential Diagnosis between Nonodontogenic and Endodontic Radiolucent Lesions in Periapical Location: A Critical Review", "heading_path": ["Body", "Results"]}]}
