{"question": "Cách xử trí đối với gãy xương gò má cung tiếp trong chẩn đoán lâm sàng là gì?", "claim": "Cần sử dụng dụng cụ thích hợp để nắn chỉnh, đưa các phần xương gãy về đúng vị trí giải phẫu trong chẩn đoán và điều trị gãy xương gò má cung tiếp.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu chuyên môn ghi nhận việc can thiệp nắn chỉnh bằng dụng cụ chuyên dụng nhằm phục hồi đúng vị trí giải phẫu của xương gãy."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Dùng dụng cụ thích hợp nắn chỉnh đưa các phần xương gãy về đúng vị trí giải phẫu."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "- Hóa trị liệu: có thể sử dụng trước phẫu thuật và phối hợp điều trị sau phẫu thuật."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["56. GÃY XƯƠNG GÒ MÁ CUNG TIẾP", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["49. UNG THƯ LƯỠI", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}]}
