{"question": "Triệu chứng cơ năng và tính chất cơn đau trong bệnh đau dây thần kinh V bao gồm những gì?", "claim": "Bệnh nhân đau dây thần kinh V thường có cơn đau khởi phát đột ngột với các tính chất như đau buốt, như dao đâm, như cháy bỏng hoặc như điện giật.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu ghi nhận cơn đau dây thần kinh V khởi phát đột ngột, mang tính chất buốt nhói, giống như dao đâm, cảm giác cháy bỏng hoặc luồng điện giật."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Đau co thắt nửa mặt (Hemifacial Spasm): đau do thần kinh VII bị kích thích, với tính chất đau kèm theo co giật các cơ một bên mặt, nhưng không dữ dội như đau thần kinh V."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "- Đau khởi phát đột ngột, với tính chất đau buốt, như dao đâm, như cháy bỏng, hay như điện giật."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["48. ĐAU DÂY THẦN KINH V", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["48. ĐAU DÂY THẦN KINH V", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "1.1.2. Cơ năng", "b. Tính chất cơn đau"]}]}
