{"question": "Phương pháp phẫu thuật kết hợp xương hàm trên bằng nẹp vít đối với gãy xương hàm trên có đường rạch qua đâu để kết hợp máu ngoài ổ mắt?", "claim": "Đường rạch qua đuôi cung mày được sử dụng trong phẫu thuật kết hợp xương hàm trên bằng nẹp vít để kết hợp máu ngoài ổ mắt.", "internal_evidence": [{"evidence_id": "I1", "content": "Phác đồ điều trị phẫu thuật kết hợp xương hàm trên bằng nẹp vít sử dụng đường rạch qua đuôi cung mày để can thiệp kết hợp máu ngoài ổ mắt."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ X quang: CT scanner, phim mặt thẳng và nghiêng, Blondeau: có hình ảnh đường gãy qua giữa xương chính mũi qua mỏm lên xương hàm trên, qua xương lệ ra ngoài cắt bờ dưới hốc mắt cạnh hoặc qua lỗ dưới ổ mắt, cắt qua 1/3 giữa xương chân bướm ngoài. Có hình ảnh mờ xoang hàm."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Đường rạch qua đuôi cung mày để kết hợp máu ngoài ổ mắt."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["55. GÃY XƯƠNG HÀM TRÊN", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.2. Gãy toàn bộ", "b. Gãy ngang"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["55. GÃY XƯƠNG HÀM TRÊN", "IV. ĐIỀU TRỊ GÃY XƯƠNG HÀM TRÊN", "2. Điều trị cụ thể", "b. Điều trị bằng phẫu thuật kết hợp xương hàm trên bằng nẹp vít"]}]}
