{"question": "Phương pháp điều trị nào được chỉ định để loại bỏ nguyên nhân gây lệch lạc răng trong trường hợp sai khớp cắn loại I do phanh môi bám thấp?", "claim": "Trong điều trị loại bỏ các nguyên nhân gây lệch lạc răng đối với sai khớp cắn loại I, chỉ định thực hiện cắt bỏ phanh môi bám thấp.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu nội bộ ghi nhận việc loại bỏ các nguyên nhân gây lệch lạc răng trong sai khớp cắn loại I bao gồm thủ thuật cắt bỏ phanh môi bám thấp."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Khe thưa giữa các răng với các mức độ khác nhau tùy trường hợp: Có thể do bất cân xứng kích thước răng và cung hàm, hoặc có răng thừa hoặc thiếu răng, hoặc có phanh môi bám thấp."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "- Cắt bỏ phanh môi bám thấp"}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["13. SAI KHỚP CẮN LOẠI I", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Trong miệng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["13. SAI KHỚP CẮN LOẠI I", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể", "b. Điều trị loại bỏ các nguyên nhân gây lệch lạc răng"]}]}
