{"question": "Khi nào cần thực hiện khám thần kinh tập trung vào các dây thần kinh sọ ở bệnh nhân đau răng?", "claim": "Khám thần kinh, tập trung vào các dây thần kinh sọ, được thực hiện ở bệnh nhân đau răng có kèm theo sốt, nhức đầu, hoặc sưng mặt.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng hướng dẫn thực hiện thăm khám thần kinh và các dây thần kinh sọ cho các trường hợp đau răng có biểu hiện sốt, đau đầu hoặc sưng vùng mặt."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "U có thể bắt nguồn từ bất kỳ loại mô nào trong và xung quanh miệng, bao gồm mô liên kết, xương, cơ và dây thần kinh. Thông thường hay gặp u hình thành trên môi, mặt bên lưỡi, sàn miệng, và vòm miệng mềm. Một số u gây đau hoặc kích thích. U có thể được phát hiện bởi bệnh nhân hoặc chỉ phát hiện khi khám."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "Khám thần kinh, tập trung vào các dây thần kinh sọ, được thực hiện ở bệnh nhân sốt, nhức đầu, hoặc sưng mặt."}], "public_sources": [{"evidence_id": "P1", "title": "Các u ở miệng", "heading_path": []}, {"evidence_id": "P2", "title": "Đau răng và nhiễm trùng", "heading_path": ["Đánh giá đau răng", "Khám thực thể"]}]}
