{"question": "Lồi xương vòm miệng là gì và thường xuất hiện ở vị trí nào trên cung hàm?", "claim": "Lồi xương vòm miệng là khối xương cứng thường gặp xảy ra dọc theo đường trung tâm của vòm miệng cứng và thường có ở hai bên.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu nội bộ mô tả lồi xương vòm miệng là khối xương chắc xuất hiện ở đường giữa vòm miệng cứng, thường xuất hiện đối xứng hai bên."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Lồi xương vòm miệng là khối xương cứng thường gặp xảy ra dọc theo đường trung tâm của vòm miệng cứng (thường là hai bên"}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "Lồi xương vòm miệng là khối xương cứng thường gặp xảy ra dọc theo đường trung tâm của vòm miệng cứng (thường là hai bên, như có thể thấy ở đây)."}], "public_sources": [{"evidence_id": "P1", "title": "Các u ở miệng", "heading_path": ["Nguyên nhân U ở miệng", "Các u miệng lành tính"]}, {"evidence_id": "P2", "title": "Các u ở miệng", "heading_path": ["Nguyên nhân U ở miệng", "Các u miệng lành tính"]}]}
