{"question": "Các thủ thuật làm trắng răng tại nhà sử dụng thành phần và nồng độ nào trên khay tùy chỉnh để đạt hiệu quả cao?", "claim": "Thủ thuật làm trắng răng tại nhà thực hiện rất hiệu quả với 10% carbamide peroxide kết hợp chất đồng trùng hợp của axit acrylic liên kết ngang với polyalkenyl polyether đựng trong khay tùy chỉnh.", "internal_evidence": [{"evidence_id": "I1", "content": "Chương 2: Giải phẫu chức năng hệ thống nhai mô tả các diện khớp ở sọ gồm lồi khớp ở phía trước và hõm khớp ở phía sau thuộc phần dưới xương thái dương."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Các thủ thuật làm trắng răng"}, {"quote_id": "P1.Q2", "evidence_id": "P1", "text": "Thực hiện bởi | Thành phần | Bình luận"}, {"quote_id": "P1.Q3", "evidence_id": "P1", "text": "Miếng dán tẩy trắng thương mại | Chứa carbamide peroxide | Rất hiệu quả"}, {"quote_id": "P2.Q4", "evidence_id": "P2", "text": "Các thủ thuật làm trắng răng"}, {"quote_id": "P2.Q5", "evidence_id": "P2", "text": "Thực hiện bởi | Thành phần | Bình luận"}, {"quote_id": "P2.Q6", "evidence_id": "P2", "text": "Ở nhà | 10% carbamide peroxide (trở thành 3,5% hydrogen peroxide khi sử dụng) và chất làm đặc có chứa chất đồng trùng hợp của axit acrylic liên kết ngang với polyalkenyl polyether được thêm vào khay tùy chỉnh | Rất hiệu quả"}], "public_sources": [{"evidence_id": "P1", "title": "Đánh giá bệnh nhân Nha khoa", "heading_path": ["Khám thực thể bệnh nhân nha khoa", "Các thủ thuật làm trắng răng"]}, {"evidence_id": "P2", "title": "Đánh giá bệnh nhân Nha khoa", "heading_path": ["Khám thực thể bệnh nhân nha khoa", "Các thủ thuật làm trắng răng"]}]}
