{"question": "Triệu chứng gõ dọc trong tổn thương sâu răng đã hình thành lỗ sâu phân biệt với viêm tủy như thế nào?", "claim": "Khi thực hiện khám gõ dọc trên răng bị sâu răng đã hình thành lỗ sâu, bệnh nhân không có cảm giác đau.", "internal_evidence": [{"evidence_id": "I1", "content": "Bảng chẩn đoán phân biệt các tổn thương sâu răng đã hình thành lỗ sâu với viêm tủy chỉ ra triệu chứng gõ dọc đối với sâu răng là không đau."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Tổn thương mất mô cứng của răng có thể rất nhỏ chỉ xác định được khi thăm khám với dấu hiệu mắc thám châm hoặc biểu hiện rõ hình ảnh lỗ sâu với các đặc điểm sau:"}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "Triệu chứng | Sâu răng | Viêm tủy răng | Tủy hoại tử"}, {"quote_id": "P2.Q3", "evidence_id": "P2", "text": "Gõ dọc | Không đau. | Đau nhẹ. | Đau nhẹ."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["4. SÂU RĂNG SỮA", "III. CHẨN ĐOÁN", "2. Chẩn đoán sâu răng giai đoạn hình thành lỗ sâu"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["4. SÂU RĂNG SỮA", "III. CHẨN ĐOÁN", "3. Chẩn đoán phân biệt", "b. Các tổn thương sâu răng đã hình thành lỗ sâu chẩn đoán phân biệt với viêm tuỷ"]}]}
