{"question": "Đặc điểm lâm sàng của niêm mạc trong bệnh nang nhái sàn miệng là gì?", "claim": "Niêm mạc trong bệnh nang nhái sàn miệng có đặc điểm mỏng căng, có thể tự vỡ ra dịch nhày trong như lòng trắng trứng có albumin và mucin, dễ nhiễm khuẩn và hay tái phát.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng nội bộ ghi nhận tổn thương nang nhái sàn miệng biểu hiện qua niêm mạc mỏng căng, dịch nhày trong, dễ nhiễm khuẩn và tái phát."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Niêm mạc mỏng căng, có thể tự vỡ ra dịch nhày trong như lòng trắng trứng có albumin và mucin, dễ nhiễm khuẩn, hay tái phát."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Nếu mủ tụ ở sau vùng trâm: bệnh cảnh lâm sàng tương tự như nhiễm khuẩn máu. Bệnh nhân ít khi bị khít hàm, sưng bên ngoài cũng ít hơn so với áp xe ở trước trâm. Trong miệng thây sưng thành bên hầu."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["26. NANG NHÁI SÀN MIỆNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1 Lâm sàng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["34. ÁP XE THÀNH BÊN HỌNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}]}
