{"question": "Cách xử trí ban đầu đối với vết thương bỏng phần mềm vùng hàm mặt gồm những gì?", "claim": "Đối với vết thương bỏng phần mềm vùng hàm mặt, tuyệt đối không được chườm lạnh, không dùng kháng sinh hay bù nước mà chỉ cần băng kín.", "internal_evidence": [{"evidence_id": "I1", "content": "Bản nháp hướng dẫn xử trí vết thương bỏng vùng hàm mặt bằng cách bỏ qua chườm lạnh và kháng sinh, chỉ tập trung băng kín vết thương."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Chườm lạnh, chống shock, bù nước, điện giải, dùng kháng sinh…."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "+ Tính chất lan truyền: Cơn đau thường lan lên nửa đầu, nửa mặt cùng bên, bệnh nhân thường chỉ khu trú được vùng đau chứ không xác định được răng đau."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["53. CHẤN THƯƠNG PHẦN MỀM VÙNG HÀM MẶT", "IV. ĐIỀ U TRỊ", "2. Điều trị cụ thể", "2.8. Vết thương bỏng"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["11. VIÊM TỦY RĂNG", "III. CHẨN ĐOÁN", "2. Viêm tủy không hồi phục", "2.1. Chẩn đoán xác định"]}]}
