{"question": "Triệu chứng đặc thù và thời gian kéo dài của viêm tủy có hồi phục khi gặp kích thích nóng lạnh là gì?", "claim": "Viêm tủy có hồi phục thường có triệu chứng nhạy cảm với các kích thích nóng, lạnh hoặc không khí, và cơn đau chỉ kéo dài vài giây hoặc vài chục giây sau khi loại bỏ kích thích.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng ghi nhận bệnh nhân viêm tủy có hồi phục thường ê buốt nhẹ khi gặp kích thích nhiệt hoặc không khí, cảm giác đau biến mất nhanh chóng sau khi ngừng kích thích."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Triệu chứng | Viêm tủy không hồi phục | Viêm tủy có hồi phục | Viêm quanh cuống cấp"}, {"quote_id": "P1.Q2", "evidence_id": "P1", "text": "Thử tủy | Đau nhiều và còn kéo dài thêm khi ngừng kích thích. | Có đau, sớm hết đau khi hết kích thích. | Không đau."}, {"quote_id": "P2.Q3", "evidence_id": "P2", "text": "+ Nếu có thường là các triệu chứng đặc thù: nhạy cảm với các kích thích nóng lạnh, không khí. Chỉ kéo dài vài giây hoặc vài chục giây sau khi loại bỏ kích thích."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["5. VIÊM TỦY RĂNG SỮA", "III. CHẨN ĐOÁN", "2. Viêm tủy răng sữa không hồi phục", "c. Chẩn đoán phân biệt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["11. VIÊM TỦY RĂNG", "III. CHẨN ĐOÁN", "1. Viêm tủy có hồi phục", "1.1. Chẩn đoán xác định"]}]}
