{"question": "Trong điều trị viêm tủy có hồi phục, bước xử trí đầu tiên đối với mô ngà là gì?", "claim": "Khi điều trị viêm tủy có hồi phục, cần sử dụng mũi khoan thích hợp để lấy bỏ toàn bộ mô ngà hoại tử.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng hướng dẫn sử dụng dụng cụ mũi khoan tương thích để loại bỏ các tổ chức ngà bị hoại tử trong viêm tủy có hồi phục."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Dùng mũi khoan thích hợp lấy bỏ mô ngà hoại tử."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "- Đối với các trường hợp đã tạo thành lỗ sâu thì phải lấy bỏ toàn bộ mô nhiễm khuẩn, bảo vệ tuỷ và hàn kín phục hồi mô cứng bằng các loại vật liệu thích hợp."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["11. VIÊM TỦY RĂNG", "IV. ĐIỀU TRỊ", "1. Viêm tủy có hồi phục"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["4. SÂU RĂNG SỮA", "IV. ĐIỀU TRỊ", "1. Nguyên tắc"]}]}
