{"question": "Triệu chứng toàn thân nào thường gặp ở bệnh nhân bị áp xe vùng sàn miệng?", "claim": "Bệnh nhân bị áp xe vùng sàn miệng thường có các biểu hiện nhiễm trùng toàn thân như sốt cao, mạch nhanh và hơi thở hôi.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng ghi nhận tình trạng nhiễm trùng toàn thân trong áp xe vùng sàn miệng bao gồm sốt cao, mạch nhanh và hôi miệng."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ Nếu mủ tụ ở sau vùng trâm: bệnh cảnh lâm sàng tương tự như nhiễm khuẩn máu. Bệnh nhân ít khi bị khít hàm, sưng bên ngoài cũng ít hơn so với áp xe ở trước trâm. Trong miệng thây sưng thành bên hầu."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "Có biểu hiện nhiễm trùng: sốt cao, mạch nhanh, hơi thở hôi…."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["34. ÁP XE THÀNH BÊN HỌNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "b. Tại chỗ"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["32. ÁP XE VÙNG SÀN MIỆNG", "III. CHẨN ĐOÁN", "1. Chẩn đoán xác định", "1.1. Lâm sàng", "a. Toàn thân"]}]}
