{"question": "Viêm tủy có hồi phục cần được chẩn đoán phân biệt với những bệnh lý nào?", "claim": "Viêm tủy có hồi phục được chẩn đoán phân biệt với sâu ngà sâu và viêm tủy không hồi phục dựa trên các dấu hiệu lâm sàng và cận lâm sàng.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng ghi nhận viêm tủy có hồi phục cần phân biệt chính xác với sâu ngà sâu và tình trạng viêm tủy không hồi phục."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Viêm tủy có hồi phục chẩn đoán phân biệt với sâu ngà sâu và viêm tủy không hồi phục: Dựa vào các dấu hiệu lâm sàng và cận lâm sàng."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "Khớp cắn hở có các biểu hiện trên lâm sàng và X quang rõ rệt, vì vậy không cần chẩn đoán phân biệt."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["11. VIÊM TỦY RĂNG", "III. CHẨN ĐOÁN", "1. Viêm tủy có hồi phục", "1.2. Chẩn đoán phân biệt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["20 . KHỚP CẮN HỞ", "III. CHẨN ĐOÁN", "2. Chẩn đoán phân biệt"]}]}
