{"question": "Ung thư sàn miệng giai đoạn IV có được điều trị bằng vạt từ xa với nối mạch vi phẫu không?", "claim": "Ung thư sàn miệng giai đoạn IV tuyệt đối không được sử dụng phương pháp vạt từ xa với nối mạch vi phẫu trong điều trị.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu nội bộ chỉ định rõ ràng có thể áp dụng phương pháp vạt từ xa với nối mạch vi phẫu cho bệnh nhân ung thư sàn miệng giai đoạn IV."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "+ hoặc vạt từ xa với nối mạch vi phẫu."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "- Can thiệp phẫu thuật chỉnh hình xương: Trong các trường hợp kém phát triển xương hàm trên nặng không thể điều trị bù trừ bằng nắn chỉnh răng đơn thuần được thì phải kết hợp chỉnh hình xương hàm trên."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["50. UNG THƯ SÀN MIỆNG", "IV. ĐIỀU TRỊ", "2. Điều trị cụ thể"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["22. SAI KHỚP CẮN LOẠI III DO KÉM PHÁT TRIỂN XƯƠNG HÀM TRÊN", "VI. ĐIỀU TRỊ", "b. Bệnh nhân hết thời kỳ tăng trưởng"]}]}
