{"question": "Dấu hiệu lâm sàng nào giúp chẩn đoán xác định vết thương tuyến nước bọt trong chấn thương phần mềm vùng hàm mặt?", "claim": "Vết thương tuyến nước bọt có biểu hiện tổn thương nhu mô tuyến nước bọt, kèm theo dấu hiệu chảy nước bọt qua vùng bị tổn thương.", "internal_evidence": [{"evidence_id": "I1", "content": "Tài liệu lâm sàng ghi nhận tổn thương nhu mô tuyến nước bọt trong chấn thương hàm mặt thường xuất hiện dấu hiệu tiết dịch nước bọt rỉ ra tại vị trí tổn thương."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "- Tổn thương nhu mô tuyến nước bọt, có thể có dấu hiệu chảy nước bọt qua vùng tổn thương."}, {"quote_id": "P2.Q2", "evidence_id": "P2", "text": "- Tổn thương niêm mạc miệng tương ứng ống tuyến và ống tuyến, có dấu hiệu chảy nước bọt qua vùng tổn thương ống tuyến."}], "public_sources": [{"evidence_id": "P1", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["53. CHẤN THƯƠNG PHẦN MỀM VÙNG HÀM MẶT", "III. CHẨ N ĐOÁ N", "1. Chẩ n đoá n xá c định", "1.7. Vết thương tuyến nước bọt"]}, {"evidence_id": "P2", "title": "Hướng dẫn chẩn đoán và điều trị một số bệnh về Răng Hàm Mặt", "heading_path": ["53. CHẤN THƯƠNG PHẦN MỀM VÙNG HÀM MẶT", "III. CHẨ N ĐOÁ N", "1. Chẩ n đoá n xá c định", "1.7. Vết thương tuyến nước bọt"]}]}
