{"question": "Tỷ lệ hiện mắc mòn răng ở nhóm trẻ từ 3 đến 5 tuổi tại Pakistan được nghiên cứu năm 2022 là bao nhiêu phần trăm?", "claim": "Tỷ lệ hiện mắc mòn răng loại mòn do cơ học ở trẻ em từ 3 đến 5 tuổi tại Pakistan theo nghiên cứu năm 2022 chiếm tới 45,8% tổng số mẫu.", "internal_evidence": [{"evidence_id": "I1", "content": "Bản nháp báo cáo tỷ lệ mòn răng nhóm tuổi 3-5 tại Pakistan năm 2022 đạt mức cao 45,8% dựa trên khảo sát lâm sàng."}], "conversation": {"history": []}, "public_quote_options": [{"quote_id": "P1.Q1", "evidence_id": "P1", "text": "Table 1"}, {"quote_id": "P1.Q2", "evidence_id": "P1", "text": "Characteristics of included studies."}, {"quote_id": "P1.Q3", "evidence_id": "P1", "text": "Authors,years | Country | Gender(M%) | age (years) | Mean HbA1c | Total sample size | Dental caries measurement | Sample size of type 1 diabetes | Mean (SD)DMFT/dmft/DMFS/dmfs"}, {"quote_id": "P1.Q4", "evidence_id": "P1", "text": "Swanljung et al,1992 | Finland | 45.90% | 12-18 | 10.9 ± 2.2% | 170 | DMFS/DMF | 85 | 5.8(5)/4.3(3.1)"}, {"quote_id": "P2.Q5", "evidence_id": "P2", "text": "Table 1"}, {"quote_id": "P2.Q6", "evidence_id": "P2", "text": "Study characteristics of included studies reporting the prevalence of tooth wear."}, {"quote_id": "P2.Q7", "evidence_id": "P2", "text": "First author | Year | Country | Sample size | Prevalence | Age | Instrument | Type of tooth wear | Qualitative assessment"}, {"quote_id": "P2.Q8", "evidence_id": "P2", "text": "Khan G. A et al. [69] | 2022 | Pakistan | 1021 | 12.2 | 3–5 | Clinicalexamination | Erosion | High"}], "public_sources": [{"evidence_id": "P1", "title": "Association between type 1 diabetes mellitus and dental caries in children and adolescents: a meta-analysis and Mendelian randomization study", "heading_path": ["Body", "Results", "Meta-analysis results", "Literature search and quality assessment results"]}, {"evidence_id": "P2", "title": "The global prevalence of tooth wear in general population: a systematic review and meta-analysis", "heading_path": ["Body", "Results"]}]}
